                      state, location, meter_installed_at, light_replacement_date,
                      pre_install_baseline, benchmark_savings_pct, eligibility_checklist,
                      created_by_id, created_at)
SELECT 'bf-mahagun-puram-ckt-1', s.id, 'bf-mahagun-puram-survey', 'lighting', 'basement',
       44, 792, 20, 24,
       'benchmark_confirmed', 'Basement',
       '2025-08-03'::date, '2025-09-21'::date,
       20.24, 62.70,
       jsonb_build_object('backfilled', true, 'source', 'signed agreement + post-installation savings report',
                          'note', 'Commissioned before this system existed — CON-16 eligibility was never assessed.',
                          'deviations', '["eligibility-never-assessed", "dates-inferred-from-readings", "benchmark-single-demo"]'::jsonb,
                          'basisNote', '44 tube lights at 20W running 24h; theoretical 21.12 kWh/day against a measured 20.24, a -4.17% variance the report records as within range. NO OVERRIDE: (20.24-7.55)/20.24 = 62.6976%, the agreed 62.70%. Both tables reproduce their stated averages - 4 pre days 04-07 Aug 2025 average 20.2375 against 20.24, 4 post days 22-25 Sep average 7.5450 against 7.55. THIS IS THE REPORT THE ''w.r.t 20.24 kWh'' LEFTOVER COMES FROM. Here the header is correct: 20.24 is this circuit''s own baseline. French Apartment''s and RG Residency''s reports carry the same header over entirely different baselines, so it was copied from this one and never updated. Neither date is stated: meter install taken as the day before the first pre-install reading (04 Aug 2025), replacement as the day before the post-install readings start (22 Sep).'),
       a.id, now()
FROM societies s, admin_users a WHERE s.name = 'Mahagun Puram' AND a.id = 'sys-data-import' ON CONFLICT DO NOTHING;
