-- The demo report. Not needed for billing, but without it the deal map sits
-- at "Demo savings report · In progress" while every later step reads done.
INSERT INTO demo_reports (id, pipeline_id, version, status,
                          pre_install_baseline_total, post_install_average_total, measured_savings_pct,
                          society_light_count, metered_light_count, extrapolation_factor,
                          projected_savings_kwh_per_day, circuit_snapshot, generated_at, shared_at, shared_by_id)
SELECT 'bf-mahagun-puram-demo-report', 'bf-mahagun-puram-pipe', 1, 'shared',
       c.pre_install_baseline, c.pre_install_baseline * (1 - c.benchmark_savings_pct / 100),
       c.benchmark_savings_pct, c.represented_light_count, c.metered_light_count,
       c.represented_light_count::double precision / c.metered_light_count,
       (c.pre_install_baseline * c.benchmark_savings_pct / 100)
         * (c.represented_light_count::double precision / c.metered_light_count),
       '[{"circuitId": "bf-mahagun-puram-ckt-1", "lightType": "basement", "location": "Basement", "meteredLightCount": 44, "representedLightCount": 792, "extrapolationFactor": 18.0, "preInstallBaseline": 20.24, "postInstallAverage": 7.55, "savedKwhPerDay": 12.69, "benchmarkSavingsPct": 62.7, "projectedSavedKwhPerDay": 228.4286, "preInstallReadings": [], "postInstallReadings": []}]'::jsonb, now(), '2025-11-16'::date, a.id
FROM circuits c, admin_users a
-- shared_by_id is an ADMIN, not a profile: FirsThing shares the report WITH
-- the society, so the sharer is internal. The mirror of offers, where
-- responded_by_id IS a profile because accepting is the society's act.
WHERE c.id = 'bf-mahagun-puram-ckt-1' AND a.id = 'sys-data-import' ON CONFLICT DO NOTHING;

INSERT INTO offers (id, pipeline_id, version, status, benchmark_source, circuit_terms,
                    tolerance_pct, revenue_share_pct, unit_electricity_rate, term_months,
                    projected_monthly_fee, issued_at, issued_by_id, responded_at, responded_by_id, created_at)
SELECT 'bf-mahagun-puram-offer', 'bf-mahagun-puram-pipe', 1, 'accepted', 'negotiated_fixed', '[{"circuitId": "bf-mahagun-puram-ckt-1", "lightType": "basement", "location": "Basement", "meteredLightCount": 44, "representedLightCount": 792, "benchmarkSavingsPct": 62.7, "preInstallBaseline": 20.24, "projectedSavedKwhPerDay": 12.6905}]'::jsonb,
       5, 53.1394, 6.93, 36,
       23221.44, '2025-11-16'::date, a.id,
       '2025-11-16'::date, p.id, now()
FROM admin_users a
LEFT JOIN societies soc ON soc.name = 'Mahagun Puram'
LEFT JOIN profiles p ON p.society_id = soc.id AND p.portal_authority = 'office_bearer' AND p.is_active
WHERE a.id = 'sys-data-import' ON CONFLICT DO NOTHING;

INSERT INTO agreements (id, pipeline_id, offer_id, prepared_at, prepared_by_id,
                        printed_at, notarized_at, signed_at, deviation_note,
                        executed_s3_key, executed_file_name, uploaded_at, uploaded_by_id)
SELECT 'bf-mahagun-puram-agreement', 'bf-mahagun-puram-pipe', 'bf-mahagun-puram-offer', '2025-11-16'::date, a.id,
       -- Printed and notarised are the same day, and it is the e-stamp
       -- certificate date on page 1 (the user, 2026-08-27). It can fall after
       -- the front-page date, which is a backdated effective date rather than
       -- a mistake.
       '2025-11-15'::date, '2025-11-15'::date,
       '2025-11-16'::date,
       -- How this deal's figures were arrived at, in the field named for it.
       -- These societies predate the system and share no single method, so
       -- the basis travels with the agreement rather than living in a CSV.
       'Commissioned before this system existed. There was no single method across these societies, so how this deal''s figures were arrived at is recorded here rather than assumed. Departures from the standard: extrapolation-theoretical, fee-device-charge-plus-share-of-net, additional-light-clause-not-applied, report-share-differs-from-agreement. SOURCE IS THE USER''S PASTED TEXT for the agreement and demo report; the invoices are real files. Every agreement figure reconciles: 700 x 20W x 24h x 30 = 10,080 kWh/month, 62.70% of it is 6,320 kWh at Rs 6.93 = Rs 43,798, less Rs 14,000 devices = Rs 29,798 net, split into Rs 23,273 and Rs 6,525 - which sum correctly but are 78.10/21.90, not the 78/22 the annexure labels them. THE ADDITIONAL-LIGHT CLAUSE WAS NOT APPLIED. 792 lights went in against a 700 minimum, and the annexure prices the extra at Rs 33 each, which would give Rs 20,525 + 92 x 33 = Rs 23,561. The June 2026 invoice, a full month, bills 792 x Rs 29.32 = Rs 23,221.44 - and Rs 29.32 is exactly the base rate, Rs 20,525/700. So every light is billed at the base rate and Rs 23,221.44 is what is recorded, with the share derived from it. Billing from 4 May 2026 - the first invoice says so on its face, ''for the month of May 2026 - From 4th May'', 28 days. That invoice prorates to exactly 0.9 of the monthly rate (Rs 26.39 of Rs 29.32) rather than 28/31, which would have been Rs 26.48. Agreement generated 15 Nov 2025 and signed 16 Nov (the user). Tolerance +/-5%, stated in clause 6. The report''s own ''50% of these verified savings'' matches neither the agreement nor the invoice.',
       'Documents/Mahagun_Puram/2025-11/Agreements/Mahagun_Puram_Agreement_2025-11-16.pdf',
       'Mahagun_Puram_Agreement_2025-11-16.pdf',
       -- The scan reaches us the day after signing.
       ('2025-11-16'::date + 1), a.id
FROM admin_users a WHERE a.id = 'sys-data-import' ON CONFLICT DO NOTHING;

INSERT INTO contracts (id, pipeline_id, society_id, service_line, agreement_id, status,
                       term_start, term_end, activated_at, activated_by_id, created_at)
SELECT 'bf-mahagun-puram-contract', 'bf-mahagun-puram-pipe', s.id, 'lighting', 'bf-mahagun-puram-agreement', 'active',
       '2026-05-04'::date, ('2026-05-04'::date + '36 months'::interval),
       '2026-05-04'::date, a.id, now()
FROM societies s, admin_users a WHERE s.name = 'Mahagun Puram' AND a.id = 'sys-data-import' ON CONFLICT DO NOTHING;

